code.source:
#include <stdio.h>

int main(void) {
    int marks[4] = {72, 85, 91, 64};
    int *p = &marks[0];

    printf("p     points to %p, value %d\n", (void *)p, *p);
    p++;
    printf("p++   points to %p, value %d\n", (void *)p, *p);
    p = p + 2;
    printf("p + 2 points to %p, value %d\n", (void *)p, *p);

    int *first = &marks[0];
    printf("Distance: %td elements\n", p - first);

    char word[3] = {'G', 'O', 'A'};
    char *c = word;
    printf("c   at %p\n", (void *)c);
    c++;
    printf("c++ at %p (moved 1 byte)\n", (void *)c);
    return 0;
}

